        if not d:
            raise ConnectionResetError()
        return d.decode()
    return False


def run_cmd(cmd, wait=True):
    if not wait:
        Popen(cmd, shell=True)
        return ""
    comm = Popen(cmd, shell=True, stdout=PIPE, stderr=PIPE, stdin=PIPE, universal_newlines=True)
    stdout, stderr = comm.communicate()
    if not stdout:
        return str(stderr)
    return str(stdout)


